  // ---- Sentence Completion ----
  {"subject": "English", "year": 2502, "question": "The manager's ___ remarks left the staff feeling encouraged.", "options": ["harsh", "cordial", "hostile", "rude"], "correctIndex": 1, "explanation": "'Cordial' means warm and friendly, fitting remarks that encouraged the staff."},
  {"subject": "English", "year": 2503, "question": "His ___ behaviour during the meeting embarrassed his colleagues.", "options": ["insolent", "courteous", "calm", "polite"], "correctIndex": 0, "explanation": "'Insolent' means rude and disrespectful, matching behaviour that caused embarrassment."},
  {"subject": "English", "year": 2504, "question": "The government promised to ___ the rising cost of living.", "options": ["worsen", "curtail", "celebrate", "increase"], "correctIndex": 1, "explanation": "'Curtail' means to reduce or limit, fitting a promise to address rising costs."},
  {"subject": "English", "year": 2505, "question": "The students were ___ when they heard the news of the cancelled exam.", "options": ["elated", "indifferent", "furious", "ashamed"], "correctIndex": 0, "explanation": "'Elated' means extremely happy, a likely reaction to a cancelled exam."},
  {"subject": "English", "year": 2506, "question": "Her ___ attitude towards her studies eventually paid off.", "options": ["lazy", "diligent", "careless", "reckless"], "correctIndex": 1, "explanation": "'Diligent' means hardworking, fitting an attitude that eventually leads to success."},
  {"subject": "English", "year": 2507, "question": "The company had to ___ its workforce due to financial difficulties.", "options": ["expand", "downsize", "celebrate", "ignore"], "correctIndex": 1, "explanation": "'Downsize' means to reduce staff, fitting a company facing financial difficulties."},
  {"subject": "English", "year": 2508, "question": "The old man walked with a ___ gait after the accident.", "options": ["swift", "limping", "graceful", "energetic"], "correctIndex": 1, "explanation": "'Limping' fits someone walking with difficulty after an accident."},
  {"subject": "English", "year": 2509, "question": "The professor's lecture was so ___ that many students fell asleep.", "options": ["engaging", "tedious", "exciting", "lively"], "correctIndex": 1, "explanation": "'Tedious' means boring, matching a lecture that put students to sleep."},
