  {"subject": "English", "year": 2516, "question": "The children were ___ about the upcoming holiday.", "options": ["excited", "indifferent", "upset", "bored"], "correctIndex": 0, "explanation": "'Excited' is the natural reaction of children anticipating a holiday."},
