  {"subject": "English", "year": 2538, "question": "The old building was declared ___ and scheduled for demolition.", "options": ["safe", "unsafe", "modern", "beautiful"], "correctIndex": 1, "explanation": "'Unsafe' fits a building condemned and scheduled for demolition."},
  {"subject": "English", "year": 2539, "question": "The students' ___ during the exam raised suspicion among the invigilators.", "options": ["honesty", "whispering", "silence", "calmness"], "correctIndex": 1, "explanation": "'Whispering' fits suspicious behaviour during an examination."},
  {"subject": "English", "year": 2540, "question": "The government's new policy aims to ___ unemployment in the country.", "options": ["increase", "reduce", "ignore", "worsen"], "correctIndex": 1, "explanation": "'Reduce' fits the stated goal of a policy addressing unemployment."},
  {"subject": "English", "year": 2541, "question": "The chairman's speech was brief but ___.", "options": ["impactful", "dull", "confusing", "lengthy"], "correctIndex": 0, "explanation": "'Impactful' fits a short speech that still made a strong impression."},

