  {"subject": "English", "year": 2542, "question": "Choose the option that correctly completes: 'If she ___ harder, she would have passed.'", "options": ["study", "studied", "had studied", "studies"], "correctIndex": 2, "explanation": "The third conditional uses the past perfect 'had studied' in the if-clause."},
  {"subject": "English", "year": 2543, "question": "Choose the option that correctly completes: 'By next year, he ___ from the university.'", "options": ["will graduate", "will have graduated", "graduates", "graduated"], "correctIndex": 1, "explanation": "Future perfect tense expresses an action that will be completed before a future point in time."},
  {"subject": "English", "year": 2544, "question": "Choose the option that correctly completes: 'The book ___ on the table belongs to me.'", "options": ["lying", "lay", "lied", "laying"], "correctIndex": 0, "explanation": "'Lying' (from 'lie', meaning to rest) correctly describes the book's position."},
  {"subject": "English", "year": 2545, "question": "Choose the option that correctly completes: 'She has been ___ English for five years.'", "options": ["learn", "learning", "learned", "learns"], "correctIndex": 1, "explanation": "Present perfect continuous tense uses 'has been + verb-ing'."},
  {"subject": "English", "year": 2546, "question": "Choose the option that correctly completes: 'Neither the manager nor his assistants ___ available.'", "options": ["was", "is", "were", "be"], "correctIndex": 2, "explanation": "With 'neither...nor', the verb agrees with the nearer subject, 'assistants', which is plural."},
  {"subject": "English", "year": 2547, "question": "Choose the option that correctly completes: 'One of the students ___ absent today.'", "options": ["are", "is", "were", "be"], "correctIndex": 1, "explanation": "'One of' is singular and takes a singular verb."},
  {"subject": "English", "year": 2548, "question": "Choose the option that correctly completes: 'The information ___ very useful.'", "options": ["were", "was", "are", "have been"], "correctIndex": 1, "explanation": "'Information' is an uncountable noun and takes a singular verb."},
  {"subject": "English", "year": 2549, "question": "Choose the option that correctly completes: 'I suggest that he ___ the report immediately.'", "options": ["submits", "submit", "submitted", "submitting"], "correctIndex": 1, "explanation": "The subjunctive mood after 'suggest that' uses the base form of the verb."},
  {"subject": "English", "year": 2550, "question": "Choose the option that correctly completes: 'Hardly had she left ___ the phone rang.'", "options": ["when", "than", "then", "before"], "correctIndex": 0, "explanation": "'Hardly...when' is the correct correlative structure."},
  {"subject": "English", "year": 2551, "question": "Choose the option that correctly completes: 'No sooner had he arrived ___ it started raining.'", "options": ["when", "than", "then", "that"], "correctIndex": 1, "explanation": "'No sooner...than' is the correct correlative structure."},
  {"subject": "English", "year": 2552, "question": "Choose the option that correctly completes: 'She is the woman ___ car was stolen.'", "options": ["who", "whom", "whose", "which"], "correctIndex": 2, "explanation": "'Whose' shows possession, referring to the woman's car."},
  {"subject": "English", "year": 2553, "question": "Choose the option that correctly completes: 'This is the house ___ I was born.'", "options": ["which", "where", "that", "who"], "correctIndex": 1, "explanation": "'Where' introduces a relative clause referring to a place."},
  {"subject": "English", "year": 2554, "question": "Choose the option that correctly completes: 'He behaves as if he ___ the owner of the company.'", "options": ["is", "were", "was", "be"], "correctIndex": 1, "explanation": "'As if' followed by a hypothetical situation uses the subjunctive 'were'."},
  {"subject": "English", "year": 2555, "question": "Choose the option that correctly completes: 'I wish I ___ more time to prepare.'", "options": ["have", "had", "has", "will have"], "correctIndex": 1, "explanation": "'Wish' followed by a past tense expresses a present unfulfilled desire."},
  {"subject": "English", "year": 2556, "question": "Choose the option that correctly completes: 'The two brothers resemble each other ___.'", "options": ["good", "well", "closely", "strong"], "correctIndex": 2, "explanation": "'Closely' is the correct adverb to describe a strong resemblance."},
