  // ---- Figures of Speech ----
  {"subject": "English", "year": 2572, "question": "Identify the figure of speech: 'O Death, where is thy sting?'", "options": ["Simile", "Apostrophe", "Metaphor", "Onomatopoeia"], "correctIndex": 1, "explanation": "Apostrophe is a figure of speech in which an absent or non-human entity is addressed directly."},
  {"subject": "English", "year": 2573, "question": "Identify the figure of speech: 'He is not the smartest student in class' (implying he is quite dull).", "options": ["Hyperbole", "Litotes", "Metaphor", "Irony"], "correctIndex": 1, "explanation": "Litotes is an understatement created by negating the opposite, softening a harsh statement."},
  {"subject": "English", "year": 2574, "question": "Identify the figure of speech: 'The bark of the tree fell as the dog began to bark.'", "options": ["Pun", "Simile", "Metaphor", "Irony"], "correctIndex": 0, "explanation": "A pun plays on the multiple meanings of a word, here 'bark' meaning tree covering and a dog's sound."},
  {"subject": "English", "year": 2575, "question": "Identify the figure of speech: 'I must be cruel only to be kind.'", "options": ["Oxymoron", "Paradox", "Simile", "Metonymy"], "correctIndex": 1, "explanation": "A paradox is a statement that seems contradictory but reveals an underlying truth."},
  {"subject": "English", "year": 2576, "question": "Identify the figure of speech: 'We shall fight on the beaches, we shall fight on the landing grounds, we shall fight in the fields.'", "options": ["Anaphora", "Antithesis", "Euphemism", "Chiasmus"], "correctIndex": 0, "explanation": "Anaphora is the repetition of a phrase at the beginning of successive clauses for emphasis."},
  {"subject": "English", "year": 2577, "question": "Identify the figure of speech: 'The rain in Spain falls mainly on the plain.'", "options": ["Assonance", "Alliteration", "Consonance", "Rhyme"], "correctIndex": 0, "explanation": "Assonance is the repetition of vowel sounds, here the repeated 'ai' sound."},
  {"subject": "English", "year": 2578, "question": "Identify the figure of speech: 'Mike likes his new bike.'", "options": ["Consonance", "Alliteration", "Assonance", "Rhyme"], "correctIndex": 0, "explanation": "Consonance is the repetition of consonant sounds within words, here the repeated 'k' sound."},
  {"subject": "English", "year": 2579, "question": "Identify the figure of speech: 'Is the Pope Catholic?' (used to imply an obviously affirmative answer).", "options": ["Rhetorical question", "Paradox", "Litotes", "Hyperbole"], "correctIndex": 0, "explanation": "A rhetorical question is asked to make a point rather than to get an actual answer."},
  {"subject": "English", "year": 2580, "question": "Identify the figure of speech: 'He met his Waterloo in the final match.'", "options": ["Allusion", "Metaphor", "Simile", "Metonymy"], "correctIndex": 0, "explanation": "Allusion is an indirect reference to a well-known event, here Napoleon's defeat at Waterloo."},
  {"subject": "English", "year": 2581, "question": "Identify the figure of speech: 'The dove flew over the peace conference.'", "options": ["Symbolism", "Metaphor", "Simile", "Personification"], "correctIndex": 0, "explanation": "Symbolism uses an object, here a dove, to represent an idea, in this case peace."},
  {"subject": "English", "year": 2582, "question": "Identify the figure of speech: 'The soldier fought bravely, fought fiercely, fought until his last breath.'", "options": ["Repetition", "Antithesis", "Euphemism", "Chiasmus"], "correctIndex": 0, "explanation": "Repetition emphasises an idea by repeating a word or phrase, here 'fought'."},
  {"subject": "English", "year": 2583, "question": "Identify the figure of speech: 'It was a tiny little pebble.'", "options": ["Tautology", "Hyperbole", "Litotes", "Oxymoron"], "correctIndex": 0, "explanation": "Tautology is the needless repetition of an idea using different words, here 'tiny' and 'little'."},
  {"subject": "English", "year": 2584, "question": "Identify the figure of speech: 'He climbed the ladder of success step by step, rung by rung, until he reached the very top.'", "options": ["Climax", "Anticlimax", "Antithesis", "Chiasmus"], "correctIndex": 0, "explanation": "Climax arranges ideas in order of increasing importance or intensity."},
  {"subject": "English", "year": 2585, "question": "Identify the figure of speech: 'The senator promised to fight for justice, freedom, and a free parking space.'", "options": ["Anticlimax", "Climax", "Hyperbole", "Euphemism"], "correctIndex": 0, "explanation": "Anticlimax is a sudden drop from something serious or important to something trivial, often for humorous effect."},
  {"subject": "English", "year": 2586, "question": "Identify the figure of speech: 'She opened the door and her heart to the stranger.'", "options": ["Zeugma", "Metaphor", "Simile", "Personification"], "correctIndex": 0, "explanation": "Zeugma uses a single word, here 'opened', to govern two other words in different senses."},

